{"explanation":"The chance is about 8.3%. Imagine 1,000 people: 10 are sick, and 9 of them test positive. Of the 990 healthy people, 99 also test positive, so only 9 of the 108 positive results come from sick people. Drag the dot to see how the answer changes when the disease is more or less common.","manimCode":"const title = new Text({ text: 'What does a positive test mean?', color: WHITE, fontSize: 34 });
title.moveTo([0, 3.3, 0]);
const population = new Text({ text: 'Out of 1,000 people', color: WHITE, fontSize: 26 });
population.moveTo([0, 2.45, 0]);
const sickHeader = new Text({ text: 'SICK', color: RED, fontSize: 25 });
sickHeader.moveTo([-3.2, 1.8, 0]);
const healthyHeader = new Text({ text: 'HEALTHY', color: BLUE, fontSize: 25 });
healthyHeader.moveTo([3.2, 1.8, 0]);
const barTitle = new Text({ text: 'Among all positive tests', color: WHITE, fontSize: 24 });
barTitle.moveTo([0, 0.1, 0]);
const formatCount = v => Math.abs(v - Math.round(v)) < 0.001 ? String(Math.round(v)) : v.toFixed(1);
let prevalence = 0.01;
let sickCount, healthyCount, trueCount, falseCount, answer;
function replaceLabel(oldLabel, message, color, size, position) {
  if (oldLabel) scene.remove(oldLabel);
  const fresh = new Text({ text: message, color, fontSize: size });
  fresh.moveTo(position);
  scene.add(fresh);
  return fresh;
}
const leftX = -5.2;
const totalWidth = 10.4;
const barBottom = -0.85;
const barTop = -0.45;
const trueBar = new Polygon({ vertices: [[leftX, barBottom, 0], [leftX + 0.8, barBottom, 0], [leftX + 0.8, barTop, 0], [leftX, barTop, 0]], color: RED });
trueBar.setFill(RED, 0.9);
const falseBar = new Polygon({ vertices: [[leftX + 0.8, barBottom, 0], [leftX + totalWidth, barBottom, 0], [leftX + totalWidth, barTop, 0], [leftX + 0.8, barTop, 0]], color: BLUE });
falseBar.setFill(BLUE, 0.75);
const sliderLine = new Line({ start: [-4.3, -2.8, 0], end: [4.3, -2.8, 0], color: GRAY });
const handle = new Dot({ point: [-3.52, -2.8, 0], color: YELLOW });
const dragHint = new Text({ text: 'Drag to change disease prevalence: 0.1% to 10%', color: GRAY, fontSize: 20 });
dragHint.moveTo([0, -3.4, 0]);
scene.add(title, population, sickHeader, healthyHeader, barTitle, trueBar, falseBar, sliderLine, handle, dragHint);
function refresh() {
  const sick = 1000 * prevalence;
  const healthy = 1000 - sick;
  const truePos = 0.9 * sick;
  const falsePos = 0.1 * healthy;
  const posterior = truePos / (truePos + falsePos);
  const split = leftX + totalWidth * posterior;
  trueBar.setVertices([[leftX, barBottom, 0], [split, barBottom, 0], [split, barTop, 0], [leftX, barTop, 0]]);
  falseBar.setVertices([[split, barBottom, 0], [leftX + totalWidth, barBottom, 0], [leftX + totalWidth, barTop, 0], [split, barTop, 0]]);
  sickCount = replaceLabel(sickCount, formatCount(sick) + ' people', RED, 25, [-3.2, 1.25, 0]);
  healthyCount = replaceLabel(healthyCount, formatCount(healthy) + ' people', BLUE, 25, [3.2, 1.25, 0]);
  trueCount = replaceLabel(trueCount, formatCount(truePos) + ' test positive', RED, 23, [-3.2, 0.7, 0]);
  falseCount = replaceLabel(falseCount, formatCount(falsePos) + ' test positive', BLUE, 23, [3.2, 0.7, 0]);
  answer = replaceLabel(answer, formatCount(truePos) + ' / (' + formatCount(truePos) + ' + ' + formatCount(falsePos) + ') = ' + (100 * posterior).toFixed(1) + '% chance of being sick', YELLOW, 27, [0, -1.65, 0]);
}
refresh();
makeDraggable(handle, scene, { constrainX: [-4.3, 4.3], constrainY: [-2.8, -2.8], onDrag: (mob, pos) => {
  const x = Math.max(-4.3, Math.min(4.3, pos[0]));
  mob.moveTo([x, -2.8, 0]);
  prevalence = 0.001 + (x + 4.3) / 8.6 * 0.099;
  refresh();
}});
await scene.wait(999999);"}

